    'leftBrace',
    'rightBrace',
    'leftBracket',
    'rightBracket',
    'bracePair',
    'bracketPair',
    'freeform',
    'mathPlus',
    'mathMinus',
    'mathMultiply',
    'mathDivide',
    'mathEqual',
    'mathNotEqual',
