        const frac = Math.max(0.03, Math.min(0.5, (adj.adj3 != null ? adj.adj3 : 25000) / 100000));
        const th = Math.min(rx, ry) * frac;
        const rx2 = Math.max(rx - th, 1),
            ry2 = Math.max(ry - th, 1);
        const [x1, y1] = pt(rx, ry, a1);
        const [x2, y2] = pt(rx, ry, a2);
        const [x3, y3] = pt(rx2, ry2, a2);
