const VoiceSelector = ({ value, onChange, label = 'Голос', className = '', gender = null }) => {
    const [isOpen, setIsOpen] = useState(false);
    const containerRef = useRef(null);
    const visibleGroups = gender
        ? VOICE_GROUPS.filter((g) => g.label.includes(gender === 'male' ? 'Чоловічі' : 'Жіночі'))
        : VOICE_GROUPS;
    useEffect(() => {
        const handleClickOutside = (e) => {
            if (containerRef.current && !containerRef.current.contains(e.target)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);
    let currentLabel = value;
    for (const group of VOICE_GROUPS) {
        for (const [v, l] of group.voices) {
            if (v === value) {
                currentLabel = l;
                break;
            }
        }
    }
    return (
        <div className={`relative ${className}`} ref={containerRef}>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className='w-full flex items-center justify-between text-[9px] font-semibold border border-slate-200 rounded px-1.5 py-0.5 outline-none focus:border-[#7c3aed] bg-white truncate'
                title={label}
            >
                <span className='truncate'>{currentLabel}</span>
                <ChevronDown size={10} className='ml-1 flex-shrink-0 text-slate-400' />
            </button>

            {isOpen && (
                <div className='absolute z-50 bottom-full mb-1 left-0 w-56 bg-white border border-slate-200 rounded-lg shadow-xl overflow-hidden flex flex-col'>
                    <div className='p-2 border-b border-slate-100 bg-slate-50 flex items-center justify-between'>
                        <span className='text-[10px] font-bold text-slate-600'>Оберіть голос</span>
                        <button
                            onClick={() => setIsOpen(false)}
                            className='text-slate-400 hover:text-slate-600 font-bold text-[10px]'
                        >
                            ✕
                        </button>
                    </div>
                    <div className='p-2 max-h-60 overflow-y-auto space-y-3 custom-scrollbar'>
                        {visibleGroups.map((group) => (
                            <div key={group.label}>
                                <div className='text-[9px] font-bold text-slate-400 mb-1 uppercase tracking-wider'>
                                    {group.label}
                                </div>
                                <div className='grid grid-cols-1 gap-0.5'>
                                    {group.voices.map(([v, l]) => (
                                        <button
                                            key={v}
                                            onClick={() => {
                                                onChange(v);
                                                setIsOpen(false);
                                            }}
                                            className={`text-left px-2 py-1.5 text-[10px] rounded transition-colors ${value === v ? 'bg-[#7c3aed] text-white font-bold' : 'hover:bg-violet-50 text-slate-700'}`}
                                        >
                                            {l}
                                        </button>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};
