const forceUnifiedFont = (slides) => {
    const fixLines = (lines) => {
        for (const l of lines || []) {
            l.font = UNIFIED_FONT;
            for (const r of l.runs || []) if (!r.math) r.font = UNIFIED_FONT;
        }
    };
    for (const sl of slides || []) {
        for (const o of sl.objects || []) {
            fixLines(o.lines);
            for (const row of o.rows || []) for (const c of row.cells || []) fixLines(c.lines);
        }
    }
    return slides;
};
const __googleFontTried = new Set();
const ensurePresentationFonts = async (names) => {
    const missing = [];
    for (const name of names) {
        if (!name || name.startsWith('+')) continue;
        try {
            if (document.fonts.check(`16px "${name}"`)) continue;
        } catch (e) { }
        if (__googleFontTried.has(name)) {
            missing.push(name);
            continue;
        }
        __googleFontTried.add(name);
        try {
            const fam = encodeURIComponent(name).replace(/%20/g, '+');
            const link = document.createElement('link');
            link.rel = 'stylesheet';
            link.href = `https://fonts.googleapis.com/css2?family=${fam}:ital,wght@0,400;0,700;1,400;1,700&display=swap`;
            document.head.appendChild(link);
            await new Promise((r) => {
                link.onload = r;
                link.onerror = r;
                setTimeout(r, 3000);
            });
            await Promise.race([document.fonts.load(`16px "${name}"`), new Promise((r) => setTimeout(r, 3000))]);
            if (!document.fonts.check(`16px "${name}"`)) missing.push(name);
        } catch (e) {
            missing.push(name);
        }
    }
    return missing;
};
const pullFontsFromSystem = async (families) => {
    try {
        const wanted = new Set(families.map((f) => String(f).toLowerCase()));
        const all = await window.queryLocalFonts();
        const loadedFams = new Set();
        const seen = new Set();
        for (const f of all) {
            const fam = (f.family || '').toLowerCase();
            if (!wanted.has(fam)) continue;
            const styleName = (f.style || '').toLowerCase();
            const weight = styleName.includes('bold') ? 'bold' : 'normal';
            const style = styleName.includes('italic') || styleName.includes('oblique') ? 'italic' : 'normal';
            const key = fam + '|' + weight + '|' + style;
            if (seen.has(key)) continue;
            seen.add(key);
            try {
                const blob = await f.blob();
                const face = new FontFace(f.family, await blob.arrayBuffer(), { weight, style });
                await face.load();
                document.fonts.add(face);
                loadedFams.add(f.family);
            } catch (e) { }
        }
        const still = families.filter(
            (fm) => !Array.from(loadedFams).some((lf) => lf.toLowerCase() === String(fm).toLowerCase()),
        );
        if (loadedFams.size) {
            toast(
                'success',
                `Шрифти взято з вашої системи: ${Array.from(loadedFams).join(', ')} — тепер точний збіг (діє у редакторі та у відео)`,
            );
        }
        if (still.length) toast('info', `У системі не знайдено: ${still.join(', ')} — лишається заміна`);
        logChange('Шрифти', 'Підвантажено шрифти з системи користувача', {
            loaded: Array.from(loadedFams),
            stillMissing: still,
        });
    } catch (e) {
        toast(
            'error',
            'Доступ до системних шрифтів не надано або браузер не підтримує (потрібен Chrome/Edge): ' +
            ((e && e.message) || e),
        );
    }
};
