        ok('detectLatin: слова → de', detectLatinLang('Tolle Arbeit!', 'en') === 'de');
        ok('detectLatin: англійська → en', detectLatinLang('Great work! See you tomorrow.', 'de') === 'en');
        ok('detectLatin: без сигналів → fallback', detectLatinLang('Wunderbar', 'de') === 'de');
        ok('pickVoice: німецька фраза при UA-голосі', pickVoiceForText('Charon-UA', 'Tolle Arbeit!', 'en') === 'Charon-DE');
        const segUaDe = splitTextByLanguage('Tolle Arbeit! Скористайтеся позначками.', 'en');
        ok('splitLang: de+uk у одному сегменті', segUaDe.length === 2 && segUaDe[0].lang === 'de' && segUaDe[1].lang === 'uk');
        ok('splitLang: мова тримається крізь паузу', splitTextByLanguage('100 %', 'en', 'uk')[0].lang === 'uk');
