        if (!o) return;
        const updates = {};
        if (mode === 'l') updates.x = 0;
        else if (mode === 'cx') updates.x = Math.round((CANVAS_W - o.w) / 2);
        else if (mode === 'r') updates.x = Math.round(CANVAS_W - o.w);
        else if (mode === 't') updates.y = 0;
        else if (mode === 'cy') updates.y = Math.round((CANVAS_H - o.h) / 2);
        else if (mode === 'b') updates.y = Math.round(CANVAS_H - o.h);
