    const splitNarrationSpeakers = (text) => {
        const segs = [];
        let speaker = 1;
        for (const part of String(text || '').split(/(\[[12]\]|\[(?:ПАУЗА|PAUSE)(?::[\d.]+)?\])/i)) {
            const mk = part.match(/^\[([12])\]$/);
            if (mk) {
                speaker = parseInt(mk[1], 10);
                continue;
            }
            const pm = part.match(/^\[(?:ПАУЗА|PAUSE)(?::([\d.]+))?\]$/i);
            if (pm) {
                const dur = pm[1] ? parseFloat(pm[1]) : 1;
                segs.push({ speaker, text: '[PAUSE]', duration: dur > 0 ? dur : 1 });
                continue;
            }
            if (part.trim()) segs.push({ speaker, text: part.trim() });
        }
        if (!segs.length && String(text || '').trim()) segs.push({ speaker: 1, text: text.trim() });
        return segs;
    };
    const pcmSilenceBase64 = (sr, seconds) => {
        const out = new Uint8Array(Math.max(1, Math.round(sr * seconds)) * 2);
        let bin = '';
        const chunk = 0x8000;
        for (let i = 0; i < out.length; i += chunk) bin += String.fromCharCode.apply(null, out.subarray(i, i + chunk));
        return btoa(bin);
    };
    // Затримка озвучки — ЛОКАЛЬНЕ налаштування слайда (slide.voiceDelay).
    // Якщо озвучка вже згенерована, тиша перешивається прямо в PCM без
    // повторного запиту до TTS: голос, наголоси й вимова не змінюються.
    const applySlideVoiceDelay = (slideId, seconds) => {
        const slide = slides.find((s) => s.id === slideId);
        if (!slide) return;
        const delay = Math.max(0, Math.min(Number(seconds) || 0, 30));
        const updates = { voiceDelay: delay };
        if (slide.audioBase64 && slide.audioDuration > 0) {
            try {
                const sr = slide.sampleRate || 24000;
                const bakedBytes = Math.max(0, Math.round((slide.voiceDelayBaked || 0) * sr)) * 2;
                const bin = atob(slide.audioBase64);
                const cur = new Uint8Array(bin.length);
                for (let i = 0; i < bin.length; i++) cur[i] = bin.charCodeAt(i);
                const core = cur.subarray(Math.min(bakedBytes, cur.length));
                const lead = new Uint8Array(Math.round(delay * sr) * 2);
                const out = new Uint8Array(lead.length + core.length);
                out.set(lead, 0);
                out.set(core, lead.length);
                let b = '';
                const CHUNK = 0x8000;
                for (let i = 0; i < out.length; i += CHUNK)
                    b += String.fromCharCode.apply(null, out.subarray(i, i + CHUNK));
                updates.audioBase64 = btoa(b);
                updates.audioDuration = pcmDurationSec(updates.audioBase64, sr);
                updates.voiceDelayBaked = delay;
            } catch (e) {
                // Не вдалося перешити PCM — затримка застосується при наступній озвучці.
            }
        }
        dispatchVideo({ type: 'UPDATE_SLIDE', slideId, updates });
    };
    const concatPcmBase64 = (list) => {
        const bufs = list.map((b64) => {
            const bin = atob(b64);
            const u = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
            return u;
        });
        const total = bufs.reduce((a, b) => a + b.length, 0);
        const out = new Uint8Array(total);
        let off = 0;
        for (const b of bufs) {
            out.set(b, off);
            off += b.length;
        }
        let bin = '';
        const chunk = 0x8000;
        for (let i = 0; i < out.length; i += chunk) bin += String.fromCharCode.apply(null, out.subarray(i, i + chunk));
        return btoa(bin);
    };
