        const ctx = canvas.getContext('2d');
        const prevC = document.createElement('canvas');
        prevC.width = CANVAS_W;
        prevC.height = CANVAS_H;
        const pc = prevC.getContext('2d');
        pc.fillStyle = '#7c3aed';
